const productInfo = $('Get Product Info').first().json;
const productLang = $('grouped by lang').first().json;

// const izsInfo = $('Checks Level #2').first().json.infoIZS || "";
// Safety documents are not sent yet: the marketplace has no field for them
const additional_images = $('Final URLs').first().json.additional_images;
const markets = $('Checks Level #1').first().json.markets;
const odooPrices = $('Get Price').all().map(i => i.json);
const websitesData = $('CDON Basic Settings').first().json.websitesData;
const currencyRates = $('Get Curency Rate').all().map(i => i.json);
const productTags = productInfo.product_tag_ids;
const taxes = productInfo.taxes_id;

const height = productInfo.feed_height;
const width  = productInfo.feed_width;
const depth  = productInfo.feed_length;
const size = String(Math.max(height, width, depth));

const countryMap = {
  "Germany": "DE",
  "Sweden": "SE",
  "Finland": "FI",
  "Denmark": "DK",
  "Spain": "ES",
  "Netherlands": "NL",
  "Belgium": "BE",
  "Romania": "RO",
  "France": "FR",
  "Italy": "IT",
  "Portugal": "PT",
  "Poland": "PL"
};

const weight = String(productInfo.weight || "");

const material = $('Get Material').first().json.material || "Not available";
const color = $('Get Material').first().json.color || "Not available";

let sku = productInfo.default_code || "";
if (sku.startsWith('SKU-')) {
  sku = sku.replace(/^SKU-/, '');
}

const images = [
  ...additional_images,
  productInfo.x_studio_link_aws,
  // izsInfo 
  // Safety documents are not sent yet
].filter(i => i && i.trim() !== "");

const standard_vat = {
  SE: 0.25,
  DK: 0.25,
  FI: 0.255
};

const reduced_vat = {
  SE: 0.12,
  DK: 0.25,
  FI: 0.14
};

let vat_type = "";
if (taxes.includes(17) || taxes.includes(66)) {
  vat_type = "reduced";
} else {
  vat_type = "standard";
}

const rateDKK = currencyRates.find(r => r.name === 'DKK')?.rate;
const rateSEK = currencyRates.find(r => r.name === 'SEK')?.rate;

const smallDK = +(13.99 * rateDKK).toFixed(2);
const standardDK = +(13.99 * rateDKK).toFixed(2);

const smallSE = +(12.99 * rateSEK).toFixed(2);
const standardSE = +(18.99 * rateSEK).toFixed(2);

const shippingTable = {
  DK: { small: smallDK, standard: standardDK },
  FI: { small: 14.99, standard: 19.99 },
  SE: { small: smallSE, standard: standardSE }
};

function getLogisticClass(product_tag_ids, market) {
  if (!Array.isArray(product_tag_ids)) return 0;
  const tags = product_tag_ids.map(t => Array.isArray(t) ? t[0] : t);

  switch (true) {
    case tags.includes(9):
      return 0; // free shipping
    case tags.includes(2):
      return shippingTable[market]?.standard || 0;
    case tags.includes(1):
      return shippingTable[market]?.small || 0;
    default:
      return 2;
  }
}

const price = websitesData
  .filter(m => markets.includes(m.market))
  .map(m => {

    const found = odooPrices.find(p =>
      p.pricelist_id &&
      typeof p.pricelist_id[1] === 'string' &&
      p.pricelist_id[1].toLowerCase().includes(m.market.toLowerCase())
    );

    if (!found) return null;

    const deliveryCost = getLogisticClass(productTags, m.market);
    const finalPrice = Number(found.fixed_price) + Number(deliveryCost);

    const vat =
      vat_type === "reduced"
        ? reduced_vat[m.market]
        : standard_vat[m.market];

    return {
      market: m.market,
      value: {
        amount_including_vat: Number(finalPrice.toFixed(2)),
        currency: found.currency_id[1],
        vat_rate: vat
      }
    };
  })
  .filter(Boolean);

const localeMap = {
  SE: "sv_SE",
  DK: "da_DK",
  FI: "fi_FI"
};

const title = markets.map(market => ({
  language: localeMap[market].replace('_', '-'),
  value: productLang[localeMap[market]]?.x_studio_name_2 || ""
}));

const description = markets.map(market => ({
  language: localeMap[market].replace('_', '-'),
  value: productLang[localeMap[market]]?.x_studio_description_unique || ""
}));

const shipping_time = markets.map(market => ({
  market,
  min: 4,
  max: 7
}));

const delivery_type = markets.map(market => ({
  market,
  value: "home_delivery"
}));

let phone = productInfo.x_studio_eu_responsible_phone_number;
if (phone) {
  phone = phone.trim().replace(/[^\d+]/g, '');
  phone = phone.replace(/^00/, '+');
  if (!phone.startsWith('+')) phone = '+' + phone;
}

const  quantity = Math.floor(productInfo.dr_free_qty) < 0 ? 0 : Math.floor(productInfo.dr_free_qty);

let status = "for sale";
if (quantity === 0) {
  status = "paused";
}

const article = {
  sku,
  gtin: $('Checks Level #1').first().json.barcode,
  brand: $('Checks Level #1').first().json.brand,
  status,
  category: "",
  quantity,
  main_image: $('Final URLs').first().json.main_img,
  markets,
  price,
  images,
  title,
  description,
  shipping_time,
  classifications: [
    { name: "CONDITION", value: "NEW" }
  ],
  delivery_type,
  properties: [
    { name: "color", value: color, language: "en-US" },
    { name: "material", value: material, language: "en-US" },
    { name: "size_cm", value: size },
    { name: "weight_kg", value: weight }
  ],
  manufacturer: {
    name: productInfo.x_studio_manufacturer_name,
    address: {
      street_address: productInfo.x_studio_eu_responsible_street,
      city: productInfo.x_studio_eu_responsible_town,
      postal_code: productInfo.x_studio_eu_responsible_post_code,
      country: countryMap[productInfo.x_studio_eu_responsible_country] || null
    },
    website: "https://ich-zapfe.de",
    email: "user@example.com",
    responsible_person: {
      name: productInfo.x_studio_eu_responsible_name,
      phone,
      email: productInfo.x_studio_eu_responsible_email
    }
  }
};

if (!images || images.length === 0) {
  delete article.images;
}

return { article };

let array_properties = $('get properties').all().flatMap(item => item.json);
let check_wee = array_properties[0].x_studio_properties_name ? (array_properties.find(f => f.x_studio_properties_name[0] === +136)?.x_studio_value.length > 2  ? true : false) : false;

let wee_allowed = true;

