const product_info = $('Get Product Info').first().json;

const main_img = "https://your-instance.example.com/web/image/product.template/" + product_info.id + "/image_1920";

const additional_images = product_info.product_template_image_ids.map(item => {
  const link = "https://your-instance.example.com/web/image/product.image/" + item + "/image_1920";
  return link
});

return {main_img, additional_images};

const root = $('grouped by lang').first().json;

const localesOrder = ["da_DK", "sv_SE", "fi_FI"];

const allowBrands = [
  "ICH-ZAPFE", "KLASEBO", "SKU-SHOP", "CELLFAST", "RAINBIRD", "KWB", "GREEN-SPLIT", "Weekiss",
  "HAPPY PEOPLE", "DRESSELHAUS", "SKU-SHOP", "NATUREN", "TESA", "SCHUMACHER", "CARSYSTEM", "SCHUTZ",
  "NICE", "BUHLER", "VOSSCHEMIE", "YACHTCARE", "Caramella", "Casadeco", "Texdecor", "Kidsdepot", "Coming Kids",
  "Egmont Toys", "Happy Horse", "just dutch", "Le Toy Van", "Folkmanis", "Mathy by Bols", "Mr Maria", "3 Sprouts",
  "Elements for Kids", "Bink Bedding", "Buokids", "Romina", "Sebra", "Sirch", "Snurk", "Superliving", "ALL CARE",
  "ARTUR GLÖCKLER GmbH", "BETEC", "PROTEC Germany", "BEVI-CLEAN", "BROUWLAND", "CIS", "DMT", "DSI", "DISPTEK Group",
  "FELOM", "Franz Matthes GmbH", "Thonhauser GmbH", "FUCHS", "GasTech GmbH", "GGV Handelsgesellschaft", "GLORIA GmbH",
  "Iberian Coppers Lda", "JUNG", "LINDR ", "MICRO MATIC", "MISA", "Oxyturbo", "ProfiGast", "RICK & JULICH",
  "SARO Gastro-Products GmbH", "SCHÄFER Produkte GmbH", "Stölzle Lausitz GmbH", "TeeSA Web GmbH & Co KG", "UBC",
  "Wecomatic", "HN Kernstützen Metallwaren GmbH Thüringen", "HBW Handel", "GARDEN STEEL"
];

const ACME = [
  "BRYZA", "ACME®", "Cepex", "Cellfast", "Sobime", "Cell Fast",
  "Hase Safety Gloves GmbH", "Rain Bird", "FIXAFLEX", "Geli GmbH", "KWB",
  "Beckmann&Brehm", "DOKAS", "Zill", "Cordes", "Cook King",
  "nmc Deutschland GmbH", "NMC", "COYOTTO GARDEN POTS", "Brandenburg Späne",
  "Pipetec GmbH", "Happy People GmbH & Co. KG", "BB-Verpackungen GmbH",
  "CORDES GmbH & Co.KG", "Dresselhaus", "ecoon", "ACME Brands",
  "acme", "BGS", "Rasenspecht",
  "Quedlinburger Saatgut GmbH", "Quedlinburger", "Naturen", "Celaflor",
  "Tesa", "Kurt Europe", "TFP Sp. z o.o.", "Schumacher PL",
  "Netbox", "Mayer Network GmbH", "Substral", "DJUX",
  "Karl Verpackungen", "KM", "Heumüller Holzwolle", "Kompackt61",
  "RRK", "Kraftfixx", "MATADOR’S BBQ Smoking Chips", "Papier Kurz",
  "MD Securepack", "Nexa", "PaperWise NL", "Induplast",
  "Lincar", "MAALDERIJ ROOSENS", "Buhl Paperform",
  "Garant Verlag", "Nuevopak GmbH", "4iQ Group sp. z o.o."
];

const availableMarkets = [];
let finalBrand = null;
let finalBarcode = null;

for (const locale of localesOrder) {

  const product = root[locale];

  if (!product) {
    return {
      reason: "Bad Locale",
      message: `Missing data for locale ${locale}`
    };
  }

  const name = product.x_studio_name_3;
  const description = product.x_studio_description_unique;
  const manufacturerNameRaw =
    product.x_studio_manufacturer_name || product.x_studio_brand_name;
  const sku = product.default_code;

  // ---------------- MARKETS ----------------
  if (name && description) {
    const market = locale.split('_')[1];
    availableMarkets.push(market);
  }

  // ---------------- VALIDATION ----------------
  if (!name) {
    return {
      reason: "Bad Fields",
      message: `Missing title for ${locale}`
    };
  }

  if (name.length < 10 || name.length > 85) {
    return {
      reason: "Bad Fields",
      message: `Invalid title length for ${locale}`
    };
  }

  if (!description) {
    return {
      reason: "Bad Fields",
      message: `Missing description for ${locale}`
    };
  }

  if (description.length < 10 || description.length > 5000) {
    return {
      reason: "Bad Fields",
      message: `Invalid description length for ${locale}`
    };
  }

  // ---------------- BARCODE ----------------
  let barcode = "";

  if (product.barcode?.length === 13) {
    barcode = product.barcode;
  } else if (product.x_studio_archive_barcode?.length === 13) {
    barcode = product.x_studio_archive_barcode;
  } else if (product.seo_product_gtin?.length === 13) {
    barcode = product.seo_product_gtin;
  } else {
    return {
      reason: "No Barcode",
      message: "Product barcode is missing"
    };
  }

  const price = product.list_price;
  if (price == null || price === false || price <= 0) {
    return {
      reason: "No Sale Price",
      locale,
      message: "Invalid product price"
    };
  }

  const manufacturerName = String(manufacturerNameRaw || "").trim();
  if (!manufacturerName || manufacturerName === "0") {
    return {
      reason: "Bad Fields",
      message: "Brand is missing or invalid"
    };
  }

  // ---------------- BRAND (resolved once) ----------------
  if (!finalBrand) {

    if (sku && sku.startsWith("WF-")) {
      finalBrand = "WESTFALIA";
      finalBarcode = barcode;
      continue;
    }

    // ACME brands
    if (ACME(b => b.toLowerCase())
        .includes(manufacturerName.toLowerCase())) {
      finalBrand = "SKU-SHOP";
      finalBarcode = barcode;
      continue;
    }

    // allowBrands normalisation
    const normalizedInput = manufacturerName
      .toLowerCase()
      .replace(/[®©™]/g, "")
      .replace(/\s+/g, "")
      .replace(/-/g, "");

    const normalizedAllowBrands = allowBrands.map(original => ({
      original,
      normalized: original
        .toLowerCase()
        .replace(/[®©™]/g, "")
        .replace(/\s+/g, "")
        .replace(/-/g, "")
    }));

    const matchedBrand = normalizedAllowBrands.find(b =>
      b.normalized.includes(normalizedInput) ||
      normalizedInput.includes(b.normalized)
    );

    if (!matchedBrand) {
      return {
        reason: "Forbidden Brand",
        message: "Brand is not in the allowed list"
      };
    }

    finalBrand = matchedBrand.original;
    finalBarcode = barcode;
  }
}

// ---------------- AFTER LOOP ----------------

if (availableMarkets.length === 0) {
  return {
    reason: "Bad Fields",
    message: "No valid locale with a title and description"
  };
}

return {
  brand: finalBrand,
  barcode: finalBarcode,
  markets: availableMarkets
};

const product = $('Get Product Info').first().json;

// Get the category name (from the previous step)
const categories_name = $input.first().json.categories_name;

// --- Try to get the PDF file (safely) ---
let pdf_file = null;
let infoIZS = null;
try {
  // Check that the node exists and has data
  const attachmentNode = $('Attachments info').first();
  if (attachmentNode && attachmentNode.json) {
    pdf_file = attachmentNode.json.x_studio_file || null;
    infoIZS = attachmentNode.json.x_studio_file_pdf || null;
  }
} catch (e) {
  // If the node did not run or is missing, ignore it; pdf_file stays null
  console.log("Attachments info missing or failed");
}

const tags = product.product_tag_ids || [];
const Image = product.image_1920;

const deliveryTags = [1, 2, 3, 4, 5, 6, 7, 8, 9];
const hasDeliveryTag = tags.some(tag => deliveryTags.includes(tag));

let output = {
  product_tag_ids: tags,
  categories_name: categories_name,
  dr_free_qty: product.dr_free_qty,
  check_delivery_tags: hasDeliveryTag,
  check_chemistry: true,
  check_image: Image !== false && Image != null,
  check_stock: product.dr_free_qty > 0,
  // eu_responsible_name: product.x_studio_eu_responsible_name,
  // eu_responsible_phone_number: product.x_studio_eu_responsible_phone_number,
  // eu_responsible_email: product.x_studio_eu_responsible_email,
  // eu_responsible_country: product.x_studio_eu_responsible_country,
  // eu_responsible_post_code: product.x_studio_eu_responsible_post_code,
  // eu_responsible_town: product.x_studio_eu_responsible_town,
  // eu_responsible_street: product.x_studio_eu_responsible_street,
  // eu_responsible_house_no: product.x_studio_eu_responsible_house_no,
  manufacturer_name: product.x_studio_manufacturer_name,
  is_published: product.is_published,
  x_studio_gpsr_image: product.x_studio_gpsr_image,
  x_studio_file: pdf_file, // <-- PDF added to the output
  infoIZS
};

// --- Delivery tags check ---
if (!hasDeliveryTag) {
  output.message = "no delivery option";
  output.reason = "No Delivery Tag";
}

// --- Forbidden tags ---
const forbiddenTags = [241, 307];
const hasForbiddenTag = tags.some(tag => forbiddenTags.includes(tag));

if (hasForbiddenTag) {
  output.message = "Product has a tag that blocks marketplace listing";
  output.reason = "Not For Marketplaces";
}

// --- Chemicals category (new logic) ---
// If the category is Chemicals (7)
if (product.categ_id && product.categ_id[0] === 7) {
  // PDF exists: skip this block (product is valid)
  // No PDF (!pdf_file): block the product
  if (!pdf_file) {
    output.check_chemistry = false;
    output.message = "Product is in the chemicals category (possible biocide): not listed (no PDF)";
    output.reason = "Not For Marketplaces";
  }
}

// --- Main image check ---
if (Image === false || Image == null) {
  output.check_image = false;
  output.message = "Main image does not exist";
  output.reason = "Bad Fields";
}

// --- Category presence check (via categories_name) ---
if (!categories_name || categories_name === false) {
  output.message = "Product has no category";
  output.reason = "Bad Fields";
}

// --- Stock check ---
if (!output.check_stock) {
  output.message = "product is out of stock";
  output.reason = "Stock Is Unavailable";
}

// --- GPSR check ---
let gpsr_bad_fields = [];
let check_gpsr = true;

const gpsr_data = {
  x_studio_eu_responsible_name: product.x_studio_eu_responsible_name,
  x_studio_eu_responsible_phone_number: product.x_studio_eu_responsible_phone_number,
  x_studio_eu_responsible_email: product.x_studio_eu_responsible_email,
  x_studio_eu_responsible_country: product.x_studio_eu_responsible_country,
  x_studio_eu_responsible_post_code: product.x_studio_eu_responsible_post_code,
  x_studio_eu_responsible_town: product.x_studio_eu_responsible_town,
  x_studio_eu_responsible_street: product.x_studio_eu_responsible_street,
  x_studio_eu_responsible_house_no: product.x_studio_eu_responsible_house_no,
  x_studio_manufacturer_name: product.x_studio_manufacturer_name,
  x_studio_gpsr_image: product.x_studio_gpsr_image
};

for (const [key, value] of Object.entries(gpsr_data)) {
  if (
    value === false ||
    value === "" ||
    value === "0" ||
    value === 0 ||
    value === "-" ||
    (typeof value === "string" && value.toLowerCase() === "#n/a") || 
    (typeof value === "string" && value.toLowerCase() === "n/a")
  ) {
    gpsr_bad_fields.push(key); 
    check_gpsr = false;
  }
}


output.check_gpsr = check_gpsr;

if (!check_gpsr) {
  output.message = "GPSR data is incomplete";
  output.reason = "No GPSR";
  output.gpsr_bad_fields = gpsr_bad_fields;
}

// --- General check ---
let total_check = [
  check_gpsr,
  output.check_image,
  output.check_chemistry, // true if Chemicals and a PDF exists
  hasDeliveryTag,
  categories_name && categories_name !== false,
  output.check_stock
].every(s => s === true);

return [{
  ...output,
  gpsr_data,
  total_check: total_check
}];

let result = $input.first().json.result;

// No categories array or it is empty: return false
if (!result || !Array.isArray(result) || result.length === 0) {
  return [{ categories_name: false }];
}

// Main logic
let categories_name = result
  .map(item => ({
    name: item.name,
    parent_name: item.parent_id ? item.parent_id[1] : "",
    prarents_and_self: item.parents_and_self,
    length: item.parents_and_self?.length || 0
  }))
  .sort((a, b) => b.length - a.length)[0];

// Category not found: return false
if (!categories_name || !categories_name.name) {
  return [{ categories_name: false }];
}

// Build the title text
let replace_name = result.find(f => f.parent_id === false)?.name + " / ";
let final_name = categories_name.parent_name.replace(replace_name, "") + " -> " + categories_name.name;

// Return the final result
return [{ categories_name: final_name || false }];
